set local lock_timeout = '5s';

create table public.consejos_diarios (
  id smallint primary key check (id > 0),
  categoria text not null check (categoria in ('trabajo', 'vida_personal', 'finanzas', 'aprendizaje', 'habitos')),
  consejo text not null unique check (char_length(btrim(consejo)) between 30 and 240)
);

comment on table public.consejos_diarios is
  'Consejos breves de contenido público para la tarjeta previa al inicio de sesión. La aplicación mezcla el catálogo por ciclos y mantiene un consejo por fecha de Costa Rica.';

alter table public.consejos_diarios enable row level security;
revoke all on table public.consejos_diarios from public, anon, authenticated;
grant select on table public.consejos_diarios to anon, authenticated;

create policy consejos_diarios_lectura_publica
  on public.consejos_diarios for select to anon, authenticated
  using (true);

